use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn demonstrate_compression (compressor : & SignatureCompressor) { println ! ("\n🎯 Compression Demonstration:") ; println ! ("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━") ; let mut freq_sorted : Vec < _ > = compressor . frequency_map . iter () . collect () ; freq_sorted . sort_by (| a , b | b . 1 . cmp (a . 1)) ; println ! ("🏆 Top 5 most common signatures:") ; let default_emoji = "❓" . to_string () ; for (i , (signature , frequency)) in freq_sorted . iter () . take (5) . enumerate () { let prime = compressor . prime_assignments . get (* signature) . unwrap_or (& 0) ; let emoji = compressor . emoji_assignments . get (* signature) . unwrap_or (& default_emoji) ; println ! ("  {}. {} {} → {} ({}% of total)" , i + 1 , emoji , signature , prime , (** frequency as f64 / compressor . frequency_map . values () . sum ::< u64 > () as f64 * 100.0) as u32) ; } println ! ("\n🎲 Rarest signatures (highest primes):") ; let mut prime_sorted : Vec < _ > = compressor . prime_assignments . iter () . collect () ; prime_sorted . sort_by_key (| & (_ , & prime) | std :: cmp :: Reverse (prime)) ; for (signature , prime) in prime_sorted . iter () . take (3) { println ! ("  {} → {} (signature lookup disabled)" , signature , prime) ; } }